function selfDivisiblePermutationCount(n) {
  const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
  const full = (1 << n) - 1;
  const dp = new Array(full + 1).fill(0);
  const placed = new Array(full + 1).fill(0);
  dp[0] = 1;

  for (let mask = 0; mask < full; mask++) {
    placed[mask] = placed[mask >> 1] + (mask & 1);
    if (dp[mask] === 0) {
      continue;
    }
    const position = placed[mask] + 1;
    for (let value = 1; value <= n; value++) {
      const bit = 1 << (value - 1);
      if ((mask & bit) === 0 && gcd(value, position) === 1) {
        dp[mask | bit] += dp[mask];
      }
    }
  }
  return dp[full];
}

