function selfDivisiblePermutationCount(n) {
  const coprime = (a, b) => {
    for (let d = 2; d <= Math.min(a, b); d++) if (a % d === 0 && b % d === 0) return false;
    return true;
  };
  const used = new Array(n + 1).fill(false);
  const place = (i) => {
    if (i > n) return 1;
    let total = 0;
    for (let v = 1; v <= n; v++) {
      if (used[v] || !coprime(v, i)) continue;
      used[v] = true;
      total += place(i + 1);
      used[v] = false;
    }
    return total;
  };
  return place(1);
}

